const cfg = $('Config').first().json;
const http = $('Fetch Applicants (Unipile)').first().json;
const response = http.body ?? http;
const statusCode = http.statusCode ?? response?.status ?? 200;

if (statusCode === 502) {
  throw new Error('Unipile 502 Bad Gateway: revisa unipile_dsn y unipile_port en Config (copialos del dashboard Unipile).');
}
if (statusCode === 503 && (response?.type === 'errors/no_client_session' || String(response?.title || '').includes('No client session'))) {
  throw new Error('Unipile 503: sesion de cuenta no activa. Reconecta la cuenta LinkedIn en Unipile y confirma DSN/puerto/account_id en Config.');
}
if (statusCode >= 400) {
  throw new Error(`Unipile HTTP ${statusCode}: ${JSON.stringify(response).slice(0, 800)}`);
}
if (response?.error || response?.title) {
  throw new Error(`Unipile error: ${response.title || response.error || JSON.stringify(response).slice(0, 800)}`);
}

const applicants = Array.isArray(response.items) ? response.items : [];

const existingRows = $('Read Existing IDs').all().map((item) => item.json);
const existingIds = new Set();

for (const row of existingRows) {
  const raw = row.application_id ?? row['application_id'] ?? row['Application ID'] ?? row['ID'] ?? Object.values(row)[0];
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    existingIds.add(String(raw).trim());
  }
}

const fresh = applicants.filter((applicant) => {
  const id = String(applicant.id ?? applicant.application_id ?? '').trim();
  return id && !existingIds.has(id);
});

if (!fresh.length) {
  return [];
}

return fresh.map((applicant) => ({
  json: {
    applicant,
    config: cfg,
  },
}));

const cfg = $json.config;
const applicant = $json.applicant;

const screening = (applicant.screening_questions || [])
  .map((q) => `P: ${q.question}\nR: ${(q.answers || []).join(', ')}`)
  .join('\n');

const experiences = applicant.work_experience || applicant.experiences || [];
const education = applicant.education || [];

const expText = experiences
  .slice(0, 10)
  .map((e) => `- ${e.position || e.title || 'Sin cargo'} @ ${e.company || 'Sin empresa'}${e.duration ? ` (${e.duration})` : ''}`)
  .join('\n');

const eduText = education
  .slice(0, 5)
  .map((e) => `- ${e.degree || ''} ${e.field_of_study || e.field || ''} (${e.school || ''})`)
  .join('\n');

const prompt = `Evalua este candidato para el puesto "${cfg.job_title}".

CONTEXTO DEL ROL:
- Co-Founder / Commercial Partner equity-based para desarrollar Parvus Media en GCC (prioridad KSA)
- NO es un empleo con salario fijo: buscamos perfil emprendedor con participación en negocio
- Industria: AdTech, media, publicidad digital, publishers, innovación marketing

CRITERIOS DEL PUESTO:
${cfg.job_criteria}

CANDIDATO:
Nombre: ${applicant.name || ''}
Headline: ${applicant.headline || ''}
Ubicacion: ${applicant.location || ''}
Perfil: ${applicant.public_profile_url || applicant.profile_url || ''}
Email: ${applicant.email_address || ''}
Telefono: ${applicant.phone_number || ''}

EXPERIENCIA LABORAL:
${expText || 'No disponible'}

EDUCACION:
${eduText || 'No disponible'}

PREGUNTAS DE FILTRO:
${screening || 'Ninguna'}

INSTRUCCIONES DE EVALUACION (OBLIGATORIAS):
- Se MUY exigente y conservador. Descarta por defecto salvo evidencia clara de encaje.
- Prioriza experiencia en agencias de medios/publicidad, publishers, AdTech o empresas reconocidas del sector publicidad digital en GCC.
- Penaliza fuertemente perfiles de marketing generalista, community, SEO/performance junior o sin trayectoria comercial/BD.
- No infieras skills, network ni experiencia GCC si no aparecen en el CV.
- "entrevistar" SOLO si score >= 8 Y cumple must-haves sin knockout.
- "dudoso" si hay señales mixtas (score 5-7).
- "descartar" si hay knockout o score <= 4.
- En gaps, indica especificamente que falta (ej: sin agencia, sin GCC, sin BD, perfil operativo).

Responde SOLO JSON valido con esta estructura exacta:
{
  "score": 0,
  "recommendation": "entrevistar|descartar|dudoso",
  "strengths": ["por que si 1", "por que si 2"],
  "gaps": ["por que no 1", "por que no 2"],
  "summary": "resumen breve",
  "argument": "explicacion en 2-3 frases de por que si o por que no"
}`;

return [
  {
    json: {
      applicant,
      config: cfg,
      prompt,
    },
  },
];

const source = $('Prepare AI Prompt').item.json;
const applicant = source.applicant;
const aiRaw = $input.first().json;

let parsed;
try {
  const content = aiRaw.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (error) {
  parsed = {
    score: 0,
    recommendation: 'dudoso',
    strengths: [],
    gaps: ['Error parseando respuesta IA'],
    summary: 'No se pudo interpretar la respuesta del modelo',
    argument: String(error.message || error),
  };
}

const applicationId = String(applicant.id ?? applicant.application_id ?? '');
const appliedAt = applicant.applied_at
  ? new Date(Number(applicant.applied_at)).toISOString()
  : '';

return [
  {
    json: {
      application_id: applicationId,
      nombre: applicant.name || '',
      perfil_url: applicant.public_profile_url || applicant.profile_url || '',
      headline: applicant.headline || '',
      email: applicant.email_address || '',
      telefono: applicant.phone_number || '',
      fecha_aplicacion: appliedAt,
      score: parsed.score ?? 0,
      recomendacion: parsed.recommendation || 'dudoso',
      por_que_si: (parsed.strengths || []).join(' | '),
      por_que_no: (parsed.gaps || []).join(' | '),
      resumen: parsed.summary || '',
      argumento: parsed.argument || parsed.summary || '',
      fecha_analisis: new Date().toISOString(),
    },
  },
];
